head.script:
scwin.__isShowLog = function(val) {
    var log = WebSquare.logger.getLog();
    return log.indexOf(val) != -1 ? true : false;
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    if (document.createEventObject) {
        el.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        el.dispatchEvent(evt);
    } else if (typeof el.ondblclick == 'function') {
        el.ondblclick();
    }
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand('pause', '500');
    // Test step 1. 샘플실행 후 name2항목의 값을 더블클릭 후 빈값 선택 > ctrl + 마우스우클릭 > 로그보기를 실행한다.
    //1. After running the sample, double-click the value of name2 item and select empty value> 
    //ctrl + right-click> Run log view.
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gv1_cell_0_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gv1_cell_0_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 1. 
    //1. The value of 'undefined' is not shown in the gridView value, 
    //and the related log is not displayed in the log 'Can not read property "label" of undefined'.
    //(Previously, the value 'undefined' is shown. Can not read property "offsetWidth" of null Ignore relevant log errors)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_0_1').innerText == ''", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__isShowLog('Cannot read property \"label\" of undefined')", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 09-Mar-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
